import{_ as l,r as a,o,c,e as t,a as p,s as i}from"./chunks/framework.CXcwiNg-.js";const g=JSON.parse('{"title":"File Column - October CMS - 4.x","titleTemplate":false,"description":"List Column","frontmatter":{"subtitle":"List Column","shortname":"File"},"headers":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}],"relativePath":"4.x/element/lists/column-file.md","filePath":"4.x/element/lists/column-file.md"}'),r={name:"4.x/element/lists/column-file.md"};function d(u,e,m,h,k,y){const s=a("pre-heading"),n=a("post-heading");return o(),c("div",null,[t(s),e[0]||(e[0]=p("h1",null,"File Column",-1)),t(n),e[1]||(e[1]=i(`<p>The <code>file</code> column displays a file attachment with an icon based on the file extension.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">attachment</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Attachment
    <span class="token key atrule">type</span><span class="token punctuation">:</span> file
</code></pre></div><p>The following properties are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>sortable</strong></td><td>disables sorting of the column. Default: <code>false</code></td></tr><tr><td><strong>clickable</strong></td><td>when enabled, the column participates in the row click action instead of linking to the file. Default: <code>true</code></td></tr><tr><td><strong>limit</strong></td><td>the maximum number of files to display. Default: <code>3</code></td></tr></tbody></table></div><p>Use the <code>sortable</code> property to disable sorting.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">attachment</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Attachment
    <span class="token key atrule">type</span><span class="token punctuation">:</span> file
    <span class="token key atrule">sortable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Use the <code>clickable</code> property to disable clicking on the file icon. When set to <code>true</code>, the file icon is displayed without a link. This is useful when you want the row click action to take precedence.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">attachment</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Attachment
    <span class="token key atrule">type</span><span class="token punctuation">:</span> file
    <span class="token key atrule">clickable</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Use the <code>limit</code> property to specify the maximum number of files to display when using an <code>attachMany</code> relationship.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">attachments</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Attachments
    <span class="token key atrule">type</span><span class="token punctuation">:</span> file
    <span class="token key atrule">limit</span><span class="token punctuation">:</span> <span class="token number">5</span>
</code></pre></div><p>The column automatically detects <code>attachOne</code> and <code>attachMany</code> relationships and displays the appropriate file icon based on the file extension. Supported file types include documents (PDF, DOC, TXT), spreadsheets (XLS, CSV), images (JPG, PNG, SVG), audio, video, code files, and archives.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./column-image.html">Image Column</a></li></ul></div>`,13))])}const b=l(r,[["render",d]]);export{g as __pageData,b as default};
